function createVoiceControlledRacingGame(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    canvas.width = 500;
    canvas.height = 500;
    const ctx = canvas.getContext('2d');

    // track parameters
    const track = {
        cx: canvas.width / 2,
        cy: canvas.height / 2,
        r: 180,
        width: 60
    };

    // obstacles
    const obstacles = [
        {x: track.cx + 0,  y: track.cy - 250, w: 40, h: 80},
        {x: track.cx + 250, y: track.cy + 0,   w: 80, h: 40},
        {x: track.cx + 0,  y: track.cy + 250, w: 40, h: 80},
        {x: track.cx - 250, y: track.cy + 0,   w: 80, h: 40}
    ];

    // car
    const car = {
        speed: 0,
        angle: 0,
        radius: 10,
        laneOffset: 0
    };

    // audio
    let audioCtx, micNode, analyser, dataArray;
    let micVolume = 0;
    let muted = false;

    // UI elements
    const controlsDiv = document.createElement('div');
    controlsDiv.style.position = 'absolute';
    controlsDiv.style.top = canvas.offsetTop + 'px';
    controlsDiv.style.left = canvas.offsetLeft + 'px';
    controlsDiv.style.width = canvas.width + 'px';
    controlsDiv.style.height = canvas.height + 'px';
    controlsDiv.style.pointerEvents = 'none';
    document.body.appendChild(controlsDiv);

    const startBtn = document.createElement('button');
    startBtn.textContent = 'Start Race';
    startBtn.style.position = 'absolute';
    startBtn.style.top = '10px';
    startBtn.style.left = '10px';
    startBtn.style.zIndex = 10;
    document.body.appendChild(startBtn);

    const muteBtn = document.createElement('button');
    muteBtn.textContent = 'Mute';
    muteBtn.style.position = 'absolute';
    muteBtn.style.top = '10px';
    muteBtn.style.left = '100px';
    muteBtn.style.zIndex = 10;
    muteBtn.disabled = true;
    document.body.appendChild(muteBtn);

    const volumeMeter = document.createElement('div');
    volumeMeter.style.position = 'absolute';
    volumeMeter.style.top = '10px';
    volumeMeter.style.left = '200px';
    volumeMeter.style.width = '120px';
    volumeMeter.style.height = '10px';
    volumeMeter.style.background = '#eee';
    volumeMeter.style.border = '1px solid #999';
    volumeMeter.style.zIndex = 10;
    const volumeBar = document.createElement('div');
    volumeBar.style.height = '100%';
    volumeBar.style.width = '0%';
    volumeBar.style.background = '#4caf50';
    volumeMeter.appendChild(volumeBar);
    document.body.appendChild(volumeMeter);

    const lapInfo = document.createElement('div');
    lapInfo.style.position = 'absolute';
    lapInfo.style.top = '40px';
    lapInfo.style.left = '10px';
    lapInfo.style.zIndex = 10;
    lapInfo.style.color = '#fff';
    lapInfo.style.textShadow = '1px 1px 2px #000';
    lapInfo.innerHTML = 'Click Start Race to begin';
    document.body.appendChild(lapInfo);

    let raceStarted = false;
    let lapStartTime = 0;
    let bestLapTime = parseFloat(localStorage.getItem('bestLap_' + canvasId)) || null;
    let currentLapTime = 0;

    function updateLapInfo() {
        if (!raceStarted) {
            lapInfo.innerHTML = 'Click Start Race to begin';
            return;
        }
        const elapsed = ((performance.now() - lapStartTime) / 1000).toFixed(2);
        let best = bestLapTime ? bestLapTime.toFixed(2) : '--';
        lapInfo.innerHTML = `Lap: ${elapsed}s  |  Best: ${best}s`;
    }

    async function initMicrophone() {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({audio: true});
            if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
            micNode = audioCtx.createMediaStreamSource(stream);
            analyser = audioCtx.createAnalyser();
            analyser.fftSize = 512;
            const bufferLength = analyser.frequencyBinCount;
            dataArray = new Uint8Array(bufferLength);
            micNode.connect(analyser);
            muteBtn.disabled = false;
        } catch (e) {
            alert('Microphone access denied.');
        }
    }

    function getMicrophoneVolume() {
        if (!analyser) return 0;
        analyser.getByteTimeDomainData(dataArray);
        let sum = 0;
        for (let i = 0; i < dataArray.length; i++) {
            const v = dataArray[i] - 128;
            sum += v * v;
        }
        const rms = Math.sqrt(sum / dataArray.length);
        return rms / 128; // normalize between 0 and 1
    }

    function drawTrack() {
        ctx.strokeStyle = '#888';
        ctx.lineWidth = track.width;
        ctx.beginPath();
        ctx.arc(track.cx, track.cy, track.r, 0, Math.PI * 2);
        ctx.stroke();
    }

    function drawObstacles() {
        ctx.fillStyle = '#d32f2f';
        obstacles.forEach(o => {
            ctx.fillRect(o.x - o.w / 2, o.y - o.h / 2, o.w, o.h);
        });
    }

    function drawCar() {
        const x = track.cx + (track.r + car.laneOffset) * Math.cos(car.angle);
        const y = track.cy + (track.r + car.laneOffset) * Math.sin(car.angle);
        ctx.save();
        ctx.translate(x, y);
        ctx.rotate(car.angle + Math.PI / 2);
        ctx.fillStyle = '#ffeb3b';
        ctx.fillRect(-car.radius, -car.radius, car.radius * 2, car.radius * 2);
        ctx.restore();
    }

    function checkCollision() {
        const x = track.cx + (track.r + car.laneOffset) * Math.cos(car.angle);
        const y = track.cy + (track.r + car.laneOffset) * Math.sin(car.angle);
        for (let o of obstacles) {
            if (x + car.radius > o.x - o.w / 2 &&
                x - car.radius < o.x + o.w / 2 &&
                y + car.radius > o.y - o.h / 2 &&
                y - car.radius < o.y + o.h / 2) {
                return true;
            }
        }
        return false;
    }

    let lastTime = performance.now();
    function gameLoop(now) {
        const dt = (now - lastTime) / 1000;
        lastTime = now;

        // clear
        ctx.clearRect(0, 0, canvas.width, canvas.height);

        // draw track
        drawTrack();
        drawObstacles();

        if (raceStarted) {
            // microphone volume controls speed
            micVolume = getMicrophoneVolume();
            const speedFactor = 200; // adjust
            car.speed = micVolume * speedFactor;
            if (muted) car.speed = 0;
            // update angle
            const travel = car.speed * dt; // pixels per second
            car.angle += travel / track.r;

            // collision detection
            if (checkCollision()) {
                car.speed *= 0.5;
            }

            // lap detection
            if (car.angle >= Math.PI * 2) {
                car.angle -= Math.PI * 2;
                const lapTime = (performance.now() - lapStartTime) / 1000;
                if (!bestLapTime || lapTime < bestLapTime) {
                    bestLapTime = lapTime;
                    localStorage.setItem('bestLap_' + canvasId, lapTime);
                }
                lapStartTime = performance.now();
            }
        }

        drawCar();

        // volume meter
        volumeBar.style.width = (micVolume * 100) + '%';

        updateLapInfo();

        requestAnimationFrame(gameLoop);
    }

    startBtn.onclick = async () => {
        if (!raceStarted) {
            await initMicrophone();
            raceStarted = true;
            lapStartTime = performance.now();
            startBtn.textContent = 'Race Running';
            startBtn.disabled = true;
        }
    };

    muteBtn.onclick = () => {
        if (!audioCtx) return;
        muted = !muted;
        muteBtn.textContent = muted ? 'Unmute' : 'Mute';
        if (!muted) {
            audioCtx.resume();
        } else {
            audioCtx.suspend();
        }
    };

    requestAnimationFrame(gameLoop);
}
